// Scope §36: map whatever failed into the standard error taxonomy, so the
// customer-facing dashboard can filter by cause and by whether a retry is
// worth attempting.
const execution = $input.first().json ?? {};
const error = execution.execution?.error ?? execution.error ?? {};
const message = String(error.message ?? 'Unknown workflow error');
const status = error.httpCode ?? error.statusCode ?? error.status;

function classify() {
  const code = Number(status);
  if (code === 401) return 'AUTHENTICATION_ERROR';
  if (code === 403) return 'PERMISSION_ERROR';
  if (code === 404) return 'SOURCE_NOT_FOUND';
  if (code === 422) return 'VALIDATION_ERROR';
  if (code === 429) return 'RATE_LIMIT';
  if (code >= 500) return 'BUILDERLYNC_API_ERROR';
  if (/timeout|etimedout|econnreset|socket hang up/i.test(message)) return 'SOURCE_TIMEOUT';
  return 'UNKNOWN_ERROR';
}

// The migration id travels on the workflow input. Without it the error cannot
// be attributed, so it is logged loudly rather than silently discarded.
const runData = execution.execution?.runData ?? {};
const inputNode = runData['Workflow Input']?.[0]?.data?.main?.[0]?.[0]?.json
  ?? runData['Migration Trigger']?.[0]?.data?.main?.[0]?.[0]?.json?.body
  ?? {};

const migrationId = inputNode.migration_id ?? null;

return [{
  json: {
    migration_id: migrationId,
    entity: inputNode.entity ?? null,
    error_code: classify(),
    message: message.slice(0, 2000),
    workflow: execution.workflow?.name ?? 'unknown',
    execution_id: execution.execution?.id ?? null,
    attributable: Boolean(migrationId),
  },
}];

// An error with no migration id cannot be shown to a customer, but it must not
// vanish either -- it usually means the workflow failed before it read its
// input, which is an infrastructure problem worth alerting on (Scope §57).
console.error('[MIG-900] Unattributable workflow failure', JSON.stringify($input.first().json));
return $input.all();
